    async def retrieve_deletion_job(
        self,
        job_id: str,
        *,
        extra_headers: Headers | None = None,
        extra_query: Query | None = None,
        extra_body: Body | None = None,
        timeout: float | httpx.Timeout | None | NotGiven = NOT_GIVEN,
    ) -> SessionDeletionJob:
        """Get a bulk session deletion job.

        Progress of a bulk session deletion that `POST /v3/sessions/delete/` answered with `202` (more than 20 matching sessions, selected by `session_numbers` or with `delete_all`). Poll every few seconds while `status` is `PENDING` or `PROCESSING`; stop when it is `COMPLETED` or `FAILED`.

        The job reports how many sessions ended in each outcome and how many it has processed, never which sessions it deleted. A `FAILED` job carries the reason in `error`; the sessions it had not reached are still in place, so repeat the deletion request to delete them.

        **Authentication:** API key in the `x-api-key` header. A job is only visible to the application that created it; any other `job_id` returns `404`. Missing or invalid credentials return `403`; this API never returns `401`.

        ``GET /v3/sessions/delete/{job_id}/``

        Args:
          job_id: The `job_id` returned with the `202` from `POST /v3/sessions/delete/`.
          extra_headers: Headers to add to (or, with ``None``, remove from) this request.
          extra_query: Query parameters to add to this request.
          extra_body: Top-level JSON fields to add to this request's body.
          timeout: Overrides the client's timeout for this request, in seconds.
        """
        return cast(
            "SessionDeletionJob",
            await self._client.request(
                "get",
                "/v3/sessions/delete/{job_id}/",
                cast_to=SessionDeletionJob,
                path_params={"job_id": job_id},
                auth="api_key",
                extra_headers=extra_headers,
                extra_query=extra_query,
                extra_body=extra_body,
                timeout=timeout,
            ),
        )

    async def update_data(
        self,
        session_id: str,
        *,
        document_type: Literal[
            "P", "DL", "ID", "RP", "SSC", "HIC", "WP", "TC", "VISA", "PSC", "BC", "OTHER"
        ]
        | str
        | None
        | NotGiven = NOT_GIVEN,
        document_subtype: str | None | NotGiven = NOT_GIVEN,
        document_number: str | None | NotGiven = NOT_GIVEN,
        personal_number: str | None | NotGiven = NOT_GIVEN,
        date_of_birth: str | _dt.date | None | NotGiven = NOT_GIVEN,
        date_of_issue: str | _dt.date | None | NotGiven = NOT_GIVEN,
        expiration_date: str | _dt.date | None | NotGiven = NOT_GIVEN,
        issuing_state: str | None | NotGiven = NOT_GIVEN,
        first_name: str | None | NotGiven = NOT_GIVEN,
        last_name: str | None | NotGiven = NOT_GIVEN,
        gender: Literal["M", "F", "U"] | str | None | NotGiven = NOT_GIVEN,
        address: str | None | NotGiven = NOT_GIVEN,
        place_of_birth: str | None | NotGiven = NOT_GIVEN,
        nationality: str | None | NotGiven = NOT_GIVEN,
        marital_status: Literal["SINGLE", "MARRIED", "DIVORCED", "WIDOWED", "UNKNOWN"]
        | str
        | NotGiven = NOT_GIVEN,
        extra_fields: Mapping[str, object] | None | NotGiven = NOT_GIVEN,
        parsed_address: SessionsUpdateDataParamsParsedAddress | None | NotGiven = NOT_GIVEN,
        node_id: str | NotGiven = NOT_GIVEN,
        extra_headers: Headers | None = None,
        extra_query: Query | None = None,
        extra_body: Body | None = None,
        timeout: float | httpx.Timeout | None | NotGiven = NOT_GIVEN,
    ) -> SessionsUpdateDataResponse:
        """Update KYC data extracted from the ID document on a verification session.

        Correct the identity fields that were extracted (OCR / NFC) from the user's ID document - misread names, dates, document numbers, and so on - after the verification has finished. Typical callers are a compliance analyst working from your own back office, or an automated reconciliation job. Every field in the body is optional: only the keys you send are written, everything else is left untouched (`PATCH` semantics).

        The session must belong to your application and be in `Approved`, `Declined`, `In Review`, or `Kyc Expired` status. Sessions in any other state (e.g. still `In Progress`) return `404` with `"No Session matches the given query."` - distinct from the `"Not found."` returned for an unknown or deleted `sessionId`. The session must also carry an ID-verification (KYC) record: sessions whose workflow never ran an ID-verification step return `404` (`"The session does not have a KYC."`). For graph workflows with multiple ID-verification steps, target a specific step with `node_id` (query parameter or body field); when omitted, the most recent KYC record is patched.

        Two derived fields are recomputed on every call: `full_name` (from `first_name` + `last_name`) and `issuing_state_name` (from `issuing_state`). If the free-text `address` changes, the server may also re-geocode it and refresh `parsed_address` (skipped for sandbox sessions). `extra_fields` and `parsed_address` are merged key-by-key rather than replaced - see the per-field descriptions for the `null`-to-delete semantics.

        Submitting at least one valid field fires the `data.updated` [webhook](/integration/webhooks) (trigger `manual_review`) - even when the submitted values equal the stored ones. When values actually change, a `KYC_DATA_UPDATED` activity entry recording the changed fields with previous and new values is appended to the session's `reviews`, visible in [Get Decision](#get-/v3/session/-sessionId-/decision/) and the console activity timeline. The session's status and decision are **not** re-evaluated - use [Update Status](#patch-/v3/session/-sessionId-/update-status/) to change the outcome. An empty JSON body (`{}`) is accepted and simply returns the current KYC data without firing the webhook.

        Accepts an API key or a console user token; either way the credential needs the `write:sessions` permission. Authentication and permission failures both return `403` - this API never responds `401`. Note that the session lookup runs before credential checks, so an unknown `sessionId` returns `404` even with missing credentials. This endpoint has a dedicated rate limit of 10 requests per minute per API key (invalid requests count too); the shared write budget of 300 requests per minute also applies.

        ``PATCH /v3/session/{sessionId}/update-data/``

        Args:
          session_id: UUID of the User Verification (KYC) session whose extracted document data you are correcting. Business (KYB) session IDs are not valid here - for company data use [Update KYB Company Data](#patch-/v3/session/-sessionId-/kyb/-companyUuid-/update-data/).
          document_type: Document type code. Accepts the short codes listed in the enum, plus six long-form aliases normalized server-side before validation: `Passport` → `P`, `Identity Card` → `ID`, `Driver's License` → `DL`, `Residence Permit` → `RP`, `Health Insurance Card` → `HIC`, `Tax Card` → `TC`. Any other value (including `PASSPORT` in caps) returns `400`.
          document_subtype: Document subtype from the document registry, including the region prefix when the registry distinguishes regional variants.
          document_number: Document number as printed on the ID.
          personal_number: Personal / national identification number where the document carries one (e.g. Spanish DNI on a passport).
          date_of_birth: Date of birth in `YYYY-MM-DD`. Any other format returns `400`.
          date_of_issue: Issue date of the document in `YYYY-MM-DD`.
          expiration_date: Expiration date of the document in `YYYY-MM-DD`.
          issuing_state: Issuing country as an ISO 3166-1 alpha-3 code. Case-insensitive (`esp` is stored as `ESP`); the human-readable `issuing_state_name` shown in [Get Decision](#get-/v3/session/-sessionId-/decision/) is recomputed from this value. Invalid codes return `400`.
          first_name: Given name(s). The stored `full_name` is recomputed as `first_name + ' ' + last_name` on every call to this endpoint.
          last_name: Family name(s). Also feeds the recomputed `full_name`.
          gender: Sex as printed on the document: `M` (male), `F` (female), or `U` (unknown). Any other value - including `X` - returns `400`.
          address: Free-text address as printed on the document. When this value changes (non-sandbox sessions only) and the structured address is still missing or incomplete, the server re-geocodes it synchronously before responding - the 200 body already reflects the refreshed `parsed_address`. The re-geocode also requires `issuing_state` to be present on the KYC record.
          place_of_birth: Place of birth as printed on the document.
          nationality: Nationality as printed on the document. Free text up to 32 characters - typically an ISO 3166-1 alpha-3 code (e.g. `ESP`), but not validated as one.
          marital_status: Marital status where the document carries it. Any other value returns `400`.
          extra_fields: Per-key overrides for document-specific extra fields (e.g. `blood_group`, `dl_categories`, `mrz_string`). Keys are merged into the existing override map: send a key with a value to set it, or with `null` / `""` to remove that key from the merged view. Send the whole field as `null` to clear all previously applied overrides. Must be a JSON object, otherwise `400`. The response always returns the merged view (OCR-extracted values with your overrides applied).
          parsed_address: Structured address. Only these nested keys are accepted: `address_type`, `city`, `region`, `street_1`, `street_2`, `postal_code`, `country` - any other key returns `400`. Per-key semantics: a value sets the key, `null` removes it. `formatted_address` is recomputed server-side by joining `street_1`, `street_2`, `city`, `region`, `postal_code`, and `country` and is returned in the response - you cannot set it directly.
          node_id: Workflow graph node whose KYC record to patch, for graph workflows with multiple ID-verification steps (also accepted as a `node_id` body field). When omitted, the most recent KYC record on the session is patched. If no KYC exists for the given node, the call returns `404` (`"The session does not have a KYC for node '<node_id>'."`).
          extra_headers: Headers to add to (or, with ``None``, remove from) this request.
          extra_query: Query parameters to add to this request.
          extra_body: Top-level JSON fields to add to this request's body.
          timeout: Overrides the client's timeout for this request, in seconds.
        """
        return cast(
            "SessionsUpdateDataResponse",
            await self._client.request(
                "patch",
                "/v3/session/{sessionId}/update-data/",
                cast_to=SessionsUpdateDataResponse,
                path_params={"sessionId": session_id},
                auth="api_key",
                query={"node_id": node_id},
                body={
                    "document_type": document_type,
                    "document_subtype": document_subtype,
                    "document_number": document_number,
                    "personal_number": personal_number,
                    "date_of_birth": date_of_birth,
                    "date_of_issue": date_of_issue,
                    "expiration_date": expiration_date,
                    "issuing_state": issuing_state,
                    "first_name": first_name,
                    "last_name": last_name,
                    "gender": gender,
                    "address": address,
                    "place_of_birth": place_of_birth,
                    "nationality": nationality,
                    "marital_status": marital_status,
                    "extra_fields": extra_fields,
                    "parsed_address": parsed_address,
                },
                extra_headers=extra_headers,
                extra_query=extra_query,
                extra_body=extra_body,
                timeout=timeout,
            ),
        )

    async def update_feature_status(
        self,
        session_id: str,
        node_id: str,
        *,
        new_status: Literal["Approved", "Declined", "In Review"] | str,
        comment: str | NotGiven = NOT_GIVEN,
        feature_type: Literal[
            "ID_VERIFICATION",
            "OCR",
            "OCR_BACK",
            "NFC",
            "LIVENESS",
            "FACE",
            "AGE_ESTIMATION",
            "AGE_VERIFICATION",
            "FACE_SEARCH",
            "FACE_MATCH",
            "IP_ANALYSIS",
            "AML",
            "PHONE",
            "PHONE_VERIFICATION",
            "EMAIL",
            "EMAIL_VERIFICATION",
            "POA",
            "PROOF_OF_ADDRESS",
            "DATABASE_VALIDATION",
            "DATA_VALIDATION",
            "QUESTIONNAIRE",
            "DOCUMENT_AI",
            "KYB_REGISTRY",
            "KYB_DOCUMENTS",
            "KYB_KEY_PEOPLE",
            "BANK_VERIFICATION",
            "GEOLOCATION",
        ]
        | str
        | NotGiven = NOT_GIVEN,
        defer_until_flow_finishes: bool | NotGiven = NOT_GIVEN,
        extra_headers: Headers | None = None,
        extra_query: Query | None = None,
        extra_body: Body | None = None,
        timeout: float | httpx.Timeout | None | NotGiven = NOT_GIVEN,
    ) -> SessionsUpdateFeatureStatusResponse:
        """Update an individual feature (step) status.

        Set the status of a single verification feature (step) within a session. Target the feature by its workflow graph `nodeId`. On non-graph workflows, whose steps have no node, use `default` and also pass `feature_type` to say which step you mean.

        Works for both User Verification (KYC) and Business Verification (KYB) sessions and every step type: ID/OCR, Liveness, Face Match, NFC, AML, Proof of Address, Phone, Email, Database Validation, Questionnaire, and the KYB registry / documents / key-people checks. This endpoint is **not** available for standalone API sessions (`session_type = API`).

        `new_status` must be one of `Approved`, `Declined`, or `In Review`, and must differ from the feature's current status.

        **When the override applies.** Without `defer_until_flow_finishes` (or with `false`) the override applies at once, as it always did; when the person is still in the flow it is recorded as `forced`. With `defer_until_flow_finishes: true` while the person is still in the flow (the session is `Not Started`, `In Progress` or `Resubmitted` and has not finished), the override is stored as `pending_until_flow_finishes` and applies when the flow finishes, after the flow reaches its own decision. On a session whose flow already ended it applies at once either way. A waiting override is cancelled instead when the person redoes its step before finishing, when a newer override on the same check replaces it, when the session leaves the flow unfinished (abandoned, expired, or decided mid-flow), or when you cancel it with `POST /v3/session/{sessionId}/features/overrides/{overrideId}/cancel/`. List a session's overrides with `GET /v3/session/{sessionId}/features/overrides/`.

        **Effect on the session.** A session that already has a decision keeps it: only the check changes. When the session has no decision yet and its workflow is waiting on exactly this step, applying the override completes the step: the workflow moves on, later steps run, and a status node can set the session decision and fire `status.updated`.

        **Webhooks and activity.** A `data.updated` webhook fires when the override applies (at once, or when the flow finishes), never while it waits or when it is cancelled. Every override is recorded in the session's activity as `FEATURE_OVERRIDE_PENDING`, `FEATURE_OVERRIDE_APPLIED` or `FEATURE_OVERRIDE_CANCELLED`, with who made it; the request's entry carries your `comment`.

        Authenticate with your API key (`x-api-key`) or a user authorization header carrying the `write:sessions` privilege; a scoped API key needs write access to decisions.

        ``PATCH /v3/session/{sessionId}/features/{nodeId}/update-status/``

        Args:
          session_id: UUID of the verification session. Accepts both user (KYC) and business (KYB) session IDs - the service resolves the ID across both session types.
          node_id: Workflow graph node ID of the feature to update (for example `feature_ocr_1`). Use the literal value `default` for non-graph (single-step) workflows where the feature has no node ID.
          new_status: Target status for this feature. Must differ from the current value.
          comment: Optional free-text note recorded on the session's review trail for this feature change.
          feature_type: Which kind of step to target. Needed on non-graph workflows (`nodeId` = `default`), where every step shares no node; optional otherwise. An unknown value returns `400`.
          defer_until_flow_finishes: While the person is still in the flow, store the override as `pending_until_flow_finishes` and apply it when the flow finishes, instead of at once. Omitted or `false`, the override applies at once. On a session whose flow already ended it applies at once either way.
          extra_headers: Headers to add to (or, with ``None``, remove from) this request.
          extra_query: Query parameters to add to this request.
          extra_body: Top-level JSON fields to add to this request's body.
          timeout: Overrides the client's timeout for this request, in seconds.
        """
        return cast(
            "SessionsUpdateFeatureStatusResponse",
            await self._client.request(
                "patch",
                "/v3/session/{sessionId}/features/{nodeId}/update-status/",
                cast_to=SessionsUpdateFeatureStatusResponse,
                path_params={"sessionId": session_id, "nodeId": node_id},
                auth="api_key",
                body={
                    "new_status": new_status,
                    "comment": comment,
                    "feature_type": feature_type,
                    "defer_until_flow_finishes": defer_until_flow_finishes,
                },
                extra_headers=extra_headers,
                extra_query=extra_query,
                extra_body=extra_body,
                timeout=timeout,
            ),
        )

    async def update_aml_hit_status(
        self,
        session_id: str,
        *,
        hit_id: str,
        review_status: Literal["Unreviewed", "Confirmed Match", "False Positive", "Inconclusive"]
        | str,
        node_id: str | NotGiven = NOT_GIVEN,
        node_id_query: str | NotGiven = NOT_GIVEN,
        extra_headers: Headers | None = None,
        extra_query: Query | None = None,
        extra_body: Body | None = None,
        timeout: float | httpx.Timeout | None | NotGiven = NOT_GIVEN,
    ) -> SessionsUpdateAmlHitStatusResponse:
        """Update an AML hit review status.

        Set the review status of a **single AML hit** (a potential sanction / PEP / watchlist / adverse-media match) returned by AML screening, without changing the overall session decision. Identify the hit by its `hit_id` (the `id` of an entry in the AML check's `hits` array - see the session decision).

        `review_status` is one of `Unreviewed`, `Confirmed Match`, `False Positive`, or `Inconclusive`. Reviewer decisions are preserved across ongoing-monitoring updates, so a hit you mark `False Positive` stays that way when the provider re-screens.

        A successful call fires a `data.updated` webhook and appends an activity entry (with actor attribution) to the session's review trail. For graph workflows with multiple AML checks, pass `node_id` to target a specific check.

        Authenticate with your API key (`x-api-key`) or a user authorization header - either must carry the `write:sessions` privilege.

        ``PATCH /v3/session/{sessionId}/update-aml-hit-status/``

        Args:
          session_id: UUID of the verification session. Accepts both user (KYC) and business (KYB) session IDs - the service resolves the ID across both session types.
          hit_id: The `id` of the hit in the AML check's `hits` array.
          review_status: The new review status for the hit.
          node_id: Optional graph node ID. Use it (here or as a query parameter) when the session has multiple AML checks.
          node_id_query: Workflow graph node ID. Required only when the session has multiple AML checks (one per node); omit it for single-AML sessions.
          extra_headers: Headers to add to (or, with ``None``, remove from) this request.
          extra_query: Query parameters to add to this request.
          extra_body: Top-level JSON fields to add to this request's body.
          timeout: Overrides the client's timeout for this request, in seconds.
        """
        return cast(
            "SessionsUpdateAmlHitStatusResponse",
            await self._client.request(
                "patch",
                "/v3/session/{sessionId}/update-aml-hit-status/",
                cast_to=SessionsUpdateAmlHitStatusResponse,
                path_params={"sessionId": session_id},
                auth="api_key",
                query={"node_id": node_id_query},
                body={"hit_id": hit_id, "review_status": review_status, "node_id": node_id},
                extra_headers=extra_headers,
                extra_query=extra_query,
                extra_body=extra_body,
                timeout=timeout,
            ),
        )

